import DashboardLayout, { type AppView } from "@/components/DashboardLayout";
import { ProductCreationDialog } from "@/components/ProductCreationDialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { useAuth } from "@/_core/hooks/useAuth";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { AlertTriangle, ArrowDownRight, ArrowUpRight, BarChart3, Box, CircleDollarSign, Download, PackagePlus, Plus, ReceiptText, Search, Share2, ShoppingBag, Sparkles, Store, Target, TrendingUp, Users, Wallet } from "lucide-react";

const money = (cents = 0) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(cents / 100);
const percent = (bps = 0) => `${(bps / 100).toLocaleString("pt-BR", { minimumFractionDigits: 1, maximumFractionDigits: 1 })}%`;
const today = () => new Date().toISOString().slice(0, 10);
const cents = (value: string) => Math.max(0, Math.round(Number(value.replace(",", ".")) * 100) || 0);
const asInputValue = (value = 0) => (value / 100).toFixed(2);

type Product = { id: number; code: string; name: string; team: string | null; league: string | null; collection: string | null; category: string | null; shirtType?: string | null; size: string | null; predominantColor?: string | null; supplierId?: number | null; supplierUrl?: string | null; notes?: string | null; status: "ativo" | "inativo"; listPriceCents: number; usdValueCents: number; quoteMicros: number; internationalShippingCents: number; domesticShippingCents: number; importFeesCents: number; packagingCostCents: number; otherCostsCents: number; stock: number; imageUrl?: string | null };
type SaleItem = { productId: number; quantity: number; unitPriceCents: number };
const appViews: AppView[] = ["dashboard", "venda", "produtos", "precificacao", "estoque", "compras", "despesas", "financeiro", "relatorios", "clientes", "fornecedores", "configuracoes"];

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow">{eyebrow}</p><h1 className="mt-2 font-display text-2xl font-semibold tracking-tight text-white sm:text-3xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-400">{description}</p></div>{action}</div>;
}

function Metric({ title, value, note, tone = "cyan", icon: Icon }: { title: string; value: string; note: string; tone?: "cyan" | "orange" | "violet" | "emerald"; icon: typeof Wallet }) {
  const colors = { cyan: "from-cyan-300/18 to-teal-500/5 text-cyan-200", orange: "from-orange-300/18 to-amber-500/5 text-orange-200", violet: "from-violet-300/18 to-purple-500/5 text-violet-200", emerald: "from-emerald-300/18 to-teal-500/5 text-emerald-200" };
  return <Card className="relative overflow-hidden border-white/8 bg-slate-950/40 shadow-none"><CardContent className="p-5"><div className={`absolute inset-x-0 top-0 h-px bg-gradient-to-r ${colors[tone].split(" ")[0]} ${colors[tone].split(" ")[1]}`} /><div className="flex items-start justify-between"><p className="text-[10px] font-bold tracking-[.15em] text-slate-500">{title}</p><div className={`grid size-9 place-items-center rounded-xl bg-gradient-to-br ${colors[tone]} ring-1 ring-white/5`}><Icon size={17} /></div></div><p className="mt-4 font-display text-2xl font-semibold tracking-tight text-white">{value}</p><p className="mt-2 text-xs text-slate-500">{note}</p></CardContent></Card>;
}

function Empty({ title, message, icon: Icon, action }: { title: string; message: string; icon: typeof Box; action?: React.ReactNode }) {
  return <div className="grid min-h-[260px] place-items-center rounded-2xl border border-dashed border-white/10 bg-slate-950/25 p-7 text-center"><div><div className="mx-auto grid size-12 place-items-center rounded-2xl bg-white/5 text-cyan-200"><Icon size={21} /></div><h3 className="mt-4 font-medium text-white">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">{message}</p>{action && <div className="mt-5">{action}</div>}</div></div>;
}

function StatusBadge({ status }: { status: string }) { const tone = status === "SEM PREÇO" || status === "BAIXA" ? "border-orange-300/25 bg-orange-300/10 text-orange-200" : status === "ATENÇÃO" ? "border-amber-300/25 bg-amber-300/10 text-amber-100" : status === "BOA" ? "border-cyan-300/25 bg-cyan-300/10 text-cyan-100" : "border-emerald-300/25 bg-emerald-300/10 text-emerald-100"; return <Badge className={`border text-[10px] ${tone}`}>{status}</Badge>; }

export default function Home() {
  const [activeView, setActiveView] = useState<AppView>(() => { const requested = new URLSearchParams(window.location.search).get("view") as AppView | null; return requested && appViews.includes(requested) ? requested : "dashboard"; });
  const [globalSearch, setGlobalSearch] = useState("");
  const [productDialog, setProductDialog] = useState(false);
  const [dashboardMonths, setDashboardMonths] = useState("6");
  const { user } = useAuth();
  const canManageProducts = user?.role === "Admin" || user?.role === "Estoque";
  const canAccessProducts = canManageProducts || user?.role === "Vendedor";
  const permittedViews: Record<string, AppView[]> = {
    Admin: ["dashboard", "venda", "produtos", "precificacao", "estoque", "compras", "despesas", "financeiro", "relatorios", "clientes", "fornecedores", "configuracoes"],
    Vendedor: ["dashboard", "venda", "produtos", "clientes"],
    Financeiro: ["dashboard", "despesas", "financeiro", "relatorios"],
    Estoque: ["dashboard", "produtos", "precificacao", "estoque", "compras", "fornecedores"],
  };
  const viewAllowed = !user || permittedViews[user.role]?.includes(activeView);
  useEffect(() => { if (user && !viewAllowed) setActiveView("dashboard"); }, [user, viewAllowed]);
  const utils = trpc.useUtils();
  const dashboard = trpc.dashboard.overview.useQuery({ months: Number(dashboardMonths) }, { enabled: Boolean(user) });
  const products = trpc.commerce.products.list.useQuery({ query: globalSearch, status: activeView === "produtos" ? "todos" : "ativo" }, { enabled: Boolean(user) });
  const globalResults = trpc.commerce.catalog.search.useQuery({ query: globalSearch }, { enabled: Boolean(user) && globalSearch.trim().length >= 2 });
  const inventory = trpc.dashboard.inventory.useQuery(undefined, { enabled: Boolean(user) && activeView === "estoque" });
  const catalog = trpc.commerce.catalog.bootstrap.useQuery(undefined, { enabled: Boolean(user) });
  const customerInsights = trpc.commerce.catalog.customerInsights.useQuery(undefined, { enabled: Boolean(user) && activeView === "clientes" });
  const expenses = trpc.commerce.expenses.list.useQuery(undefined, { enabled: Boolean(user) && (activeView === "despesas" || activeView === "financeiro") });
  const sales = trpc.commerce.sales.list.useQuery(undefined, { enabled: Boolean(user) && (activeView === "financeiro" || activeView === "relatorios") });
  const cashflow = trpc.commerce.finance.cashflow.useQuery(undefined, { enabled: Boolean(user) && activeView === "financeiro" });
  const settings = trpc.commerce.settings.get.useQuery(undefined, { enabled: Boolean(user) });
  const createProduct = trpc.commerce.products.create.useMutation({ onSuccess: data => { toast.success(`${data.code} cadastrado com sucesso.`); setProductDialog(false); utils.commerce.products.list.invalidate(); }, onError: error => toast.error(error.message) });
  const updateProduct = trpc.commerce.products.update.useMutation({ onSuccess: () => { toast.success("Produto atualizado."); utils.commerce.products.list.invalidate(); }, onError: error => toast.error(error.message || "Não foi possível atualizar o produto.") });
  const addProductStock = trpc.commerce.products.addStock.useMutation({ onSuccess: () => { toast.success("Estoque atualizado."); utils.invalidate(); }, onError: error => toast.error(error.message) });
  const createPurchase = trpc.commerce.purchases.create.useMutation({ onSuccess: () => { toast.success("Compra registrada e estoque atualizado."); utils.invalidate(); }, onError: error => toast.error(error.message) });
  const createSale = trpc.commerce.sales.create.useMutation({ onSuccess: result => { toast.success(`Venda concluída: lucro de ${money(result.totals.profitCents)}.`); utils.invalidate(); setActiveView("dashboard"); }, onError: (error, variables) => { if (error.message.startsWith("MARGEM ABAIXO") && window.confirm(`${error.message}\n\nDeseja concluir esta venda mesmo assim?`)) { createSale.mutate({ ...variables, confirmLowMargin: true }); return; } toast.error(error.message); } });
  const createExpense = trpc.commerce.expenses.create.useMutation({ onSuccess: () => { toast.success("Despesa registrada no financeiro."); utils.invalidate(); }, onError: error => toast.error(error.message) });
  const saveSettings = trpc.commerce.settings.update.useMutation({ onSuccess: () => { toast.success("Configurações atualizadas e cotação registrada no histórico."); utils.invalidate(); }, onError: error => toast.error(error.message) });
  const saveSupplier = trpc.commerce.catalog.saveSupplier.useMutation({ onSuccess: () => { toast.success("Fornecedor salvo."); utils.commerce.catalog.bootstrap.invalidate(); }, onError: error => toast.error(error.message) });
  const saveCustomer = trpc.commerce.catalog.saveCustomer.useMutation({ onSuccess: () => { toast.success("Cliente salvo."); utils.commerce.catalog.bootstrap.invalidate(); utils.commerce.catalog.customerInsights.invalidate(); }, onError: error => toast.error(error.message) });
  const saveSaleChannel = trpc.commerce.catalog.saveSaleChannel.useMutation({ onSuccess: () => { toast.success("Canal de venda salvo."); utils.commerce.catalog.bootstrap.invalidate(); }, onError: error => toast.error(error.message) });
  const savePaymentMethod = trpc.commerce.catalog.savePaymentMethod.useMutation({ onSuccess: () => { toast.success("Forma de pagamento salva."); utils.commerce.catalog.bootstrap.invalidate(); }, onError: error => toast.error(error.message) });
  const alertCount = dashboard.data?.alerts.length ?? 0;

  const exportCsv = () => { const rows = products.data ?? []; const content = ["Código;Produto;Time;Tamanho;Estoque;Preço", ...rows.map(product => [product.code, product.name, product.team ?? "", product.size ?? "", product.stock, (product.listPriceCents / 100).toFixed(2)].join(";"))].join("\n"); const url = URL.createObjectURL(new Blob([content], { type: "text/csv;charset=utf-8;" })); const link = document.createElement("a"); link.href = url; link.download = "relatorio-produtos.csv"; link.click(); URL.revokeObjectURL(url); toast.success("Arquivo CSV preparado para download."); };

  const searchResults = globalResults.data ? [...globalResults.data.products, ...globalResults.data.customers, ...globalResults.data.suppliers, ...globalResults.data.sales, ...globalResults.data.purchases] : [];
  const queryError = [dashboard.error, products.error, catalog.error, inventory.error, customerInsights.error, expenses.error, sales.error, cashflow.error, settings.error].find(Boolean);
  return <DashboardLayout activeView={activeView} onViewChange={setActiveView} alertCount={alertCount} globalSearchResults={searchResults} onGlobalResultSelect={result => { const views: Record<string, AppView> = { Produto: "produtos", Cliente: "clientes", Fornecedor: "fornecedores", Venda: "financeiro", Compra: "compras" }; setActiveView(views[result.type] ?? "dashboard"); }} onGlobalSearch={value => { setGlobalSearch(value); if (value.trim() && canAccessProducts) setActiveView("produtos"); }}>
    {queryError && <div role="alert" className="mb-5 flex flex-col gap-3 rounded-2xl border border-orange-300/25 bg-orange-300/10 p-4 text-sm sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium text-orange-100">Não foi possível atualizar todos os dados.</p><p className="mt-1 text-xs text-orange-100/75">Verifique a conexão e tente novamente. As informações já carregadas continuam disponíveis.</p></div><Button variant="outline" onClick={() => utils.invalidate()} className="border-orange-300/25 bg-transparent text-orange-100 hover:bg-orange-300/10 hover:text-orange-50">Tentar novamente</Button></div>}
    {!viewAllowed ? <Empty title="Acesso restrito" message="Seu perfil não tem permissão para abrir esta área." icon={AlertTriangle} /> : <>
    {activeView === "dashboard" && <DashboardPage data={dashboard.data} loading={dashboard.isLoading} months={dashboardMonths} onMonthsChange={setDashboardMonths} onNavigate={setActiveView} />}
    {activeView === "venda" && <QuickSale products={products.data ?? []} channels={catalog.data?.channels ?? []} methods={catalog.data?.methods ?? []} settings={settings.data} onSubmit={input => createSale.mutate(input)} pending={createSale.isPending} />}
    {activeView === "produtos" && <ProductsPage products={products.data ?? []} suppliers={catalog.data?.suppliers ?? []} loading={products.isLoading} onAdd={() => setProductDialog(true)} onArchive={id => updateProduct.mutate({ id, status: "inativo" })} onEdit={(product: Product, changes: any) => updateProduct.mutate({ id: product.id, ...changes })} onAddStock={(product: Product, quantity: string, cost: string) => addProductStock.mutate({ productId: product.id, quantity: Number(quantity), unitCostCents: cents(cost) })} settings={settings.data} canManage={canManageProducts} />}
    {activeView === "precificacao" && <PricingPage products={products.data ?? []} settings={settings.data} />}
    {activeView === "estoque" && <InventoryPage products={inventory.data ?? []} dashboard={dashboard.data} loading={inventory.isLoading} onNavigate={setActiveView} />}
    {activeView === "compras" && <PurchasePage products={products.data ?? []} suppliers={catalog.data?.suppliers ?? []} methods={catalog.data?.methods ?? []} onSubmit={input => createPurchase.mutate(input)} pending={createPurchase.isPending} />}
    {activeView === "despesas" && <ExpensesPage rows={expenses.data ?? []} onSubmit={input => createExpense.mutate(input)} pending={createExpense.isPending} />}
    {activeView === "financeiro" && <FinancialPage dashboard={dashboard.data} sales={sales.data ?? []} expenses={expenses.data ?? []} cashflow={cashflow.data} />}
    {activeView === "relatorios" && <ReportsPage products={products.data ?? []} dashboard={dashboard.data} months={dashboardMonths} onMonthsChange={setDashboardMonths} onExport={exportCsv} onPrint={() => window.print()} />}
    {activeView === "clientes" && <DirectoryPage type="clientes" rows={customerInsights.data ?? catalog.data?.customers ?? []} canManage={user?.role === "Admin" || user?.role === "Vendedor"} pending={saveCustomer.isPending} onSubmit={input => saveCustomer.mutate(input)} />}
    {activeView === "fornecedores" && <DirectoryPage type="fornecedores" rows={catalog.data?.suppliers ?? []} canManage={user?.role === "Admin" || user?.role === "Estoque"} pending={saveSupplier.isPending} onSubmit={input => saveSupplier.mutate(input)} />}
    {activeView === "configuracoes" && <AdvancedSettingsPage settings={settings.data} channels={catalog.data?.channels ?? []} methods={catalog.data?.methods ?? []} onSubmit={input => saveSettings.mutate(input)} onSaveChannel={input => saveSaleChannel.mutate(input)} onSaveMethod={input => savePaymentMethod.mutate(input)} pending={saveSettings.isPending || saveSaleChannel.isPending || savePaymentMethod.isPending} />}
    </>}
    <ProductCreationDialog open={productDialog} onOpenChange={setProductDialog} onSubmit={input => createProduct.mutate(input as any)} pending={createProduct.isPending} />
  </DashboardLayout>;
}

function DashboardPage({ data, loading, months, onMonthsChange, onNavigate }: { data: any; loading: boolean; months: string; onMonthsChange: (months: string) => void; onNavigate: (view: AppView) => void }) {
  if (loading) return <div className="space-y-5"><div className="h-20 animate-pulse rounded-2xl bg-white/5" /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{Array.from({ length: 8 }, (_, index) => <div key={index} className="h-36 animate-pulse rounded-2xl bg-white/5" />)}</div></div>;
  const kpi = data?.kpis;
  return <><SectionHeading eyebrow="VISÃO EXECUTIVA • MÊS CORRENTE" title="Comando da operação." description="Acompanhe a saúde financeira, o ritmo de vendas e os sinais de estoque antes de tomar a próxima decisão." action={<div className="flex flex-wrap gap-2"><Select value={months} onValueChange={onMonthsChange}><SelectTrigger aria-label="Período do painel" className="h-10 w-[130px] border-white/10 bg-white/5 text-slate-200"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="3">3 meses</SelectItem><SelectItem value="6">6 meses</SelectItem><SelectItem value="12">12 meses</SelectItem></SelectContent></Select><Button variant="outline" onClick={() => onNavigate("relatorios")} className="border-white/10 bg-white/5 text-slate-200 hover:bg-white/10 hover:text-white"><BarChart3 size={15} />Relatórios</Button><Button onClick={() => onNavigate("venda")} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200"><ShoppingBag size={15} />Venda rápida</Button></div>} />
  <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric title="FATURAMENTO" value={money(kpi?.revenueCents)} note={`${kpi?.revenueChangeBps == null ? "Sem comparativo anterior" : `${kpi.revenueChangeBps >= 0 ? "↑" : "↓"} ${percent(Math.abs(kpi.revenueChangeBps))} vs. mês anterior`} • ${kpi?.revenueGoalCents ? Math.round((kpi.revenueCents / kpi.revenueGoalCents) * 100) : 0}% da meta`} icon={TrendingUp} /><Metric title="LUCRO LÍQUIDO" value={money(kpi?.netProfitCents)} note={`${kpi?.profitChangeBps == null ? "Sem comparativo anterior" : `${kpi.profitChangeBps >= 0 ? "↑" : "↓"} ${percent(Math.abs(kpi.profitChangeBps))} vs. mês anterior`} • margem ${percent(kpi?.marginBps)}`} tone="emerald" icon={Sparkles} /><Metric title="VALOR EM ESTOQUE" value={money(kpi?.stockValueCents)} note={`${kpi?.stockUnits ?? 0} peças disponíveis`} tone="violet" icon={Box} /><Metric title="TICKET MÉDIO" value={money(kpi?.ticketCents)} note={`${kpi?.piecesSold ?? 0} peças vendidas`} tone="orange" icon={Target} /></div>
  <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric title="INVESTIDO NO ESTOQUE" value={money(kpi?.stockValueCents)} note="Custo dos lotes ainda disponíveis" tone="orange" icon={Wallet} /><Metric title="POTENCIAL DE ESTOQUE" value={money(kpi?.potentialStockValueCents)} note="Venda possível pelo preço atual" tone="emerald" icon={TrendingUp} /><Metric title="META DE PEÇAS" value={`${kpi?.piecesSold ?? 0}/${kpi?.unitsGoal ?? 0}`} note="Peças vendidas no mês" tone="violet" icon={ShoppingBag} /><Metric title="RITMO NECESSÁRIO" value={money(kpi?.revenueNeededPerDayCents)} note={`Por dia para alcançar ${percent(kpi?.goalProgressBps)} da meta`} icon={Target} /></div>
  <div className="mt-5 grid gap-5 xl:grid-cols-[1.65fr_1fr]"><Card className="border-white/8 bg-slate-950/40 shadow-none"><CardContent className="p-5 sm:p-6"><div className="mb-5 flex items-start justify-between"><div><p className="text-sm font-medium text-white">Evolução financeira</p><p className="mt-1 text-xs text-slate-500">Faturamento, custos, despesas e lucro nos últimos seis meses.</p></div><Badge className="border-cyan-300/15 bg-cyan-300/10 text-cyan-100">RESULTADO</Badge></div><div className="h-[280px]">{data?.chart?.some((item: any) => item.faturamento) ? <ResponsiveContainer width="100%" height="100%"><AreaChart data={data.chart}><defs><linearGradient id="revenueFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#67e8f9" stopOpacity={.38} /><stop offset="100%" stopColor="#67e8f9" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="rgba(255,255,255,.06)" /><XAxis dataKey="label" tickLine={false} axisLine={false} tick={{ fill: "#64748b", fontSize: 11 }} /><YAxis tickFormatter={value => `R$${value}`} tickLine={false} axisLine={false} tick={{ fill: "#64748b", fontSize: 11 }} /><Tooltip contentStyle={{ background: "#0f172a", border: "1px solid rgba(255,255,255,.12)", borderRadius: 12, color: "#f8fafc" }} formatter={(value: number) => money(Math.round(value * 100))} /><Area type="monotone" dataKey="faturamento" stroke="#67e8f9" strokeWidth={2.5} fill="url(#revenueFill)" /><Area type="monotone" dataKey="lucro" stroke="#fb923c" strokeWidth={2} fill="none" /></AreaChart></ResponsiveContainer> : <Empty title="Sem operações no período" message="Ao registrar suas primeiras compras e vendas, o gráfico passa a revelar o ritmo do negócio." icon={BarChart3} action={<Button size="sm" onClick={() => onNavigate("compras")} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">Registrar compra</Button>} />}</div></CardContent></Card>
  <div className="space-y-5"><Card className="border-white/8 bg-slate-950/40 shadow-none"><CardContent className="p-5"><div className="flex items-center justify-between"><div><p className="text-sm font-medium text-white">Alertas inteligentes</p><p className="mt-1 text-xs text-slate-500">Sinais que pedem ação.</p></div><span className="grid size-8 place-items-center rounded-xl bg-orange-300/10 text-orange-200"><AlertTriangle size={16} /></span></div><div className="mt-4 space-y-2">{data?.alerts?.length ? data.alerts.slice(0, 4).map((alert: any) => <div key={alert.id} className="rounded-xl border border-white/6 bg-white/[.025] p-3"><p className="text-xs font-medium text-slate-200">{alert.title}</p><p className="mt-1 line-clamp-2 text-[11px] leading-4 text-slate-500">{alert.message}</p></div>) : <p className="rounded-xl border border-dashed border-white/8 p-4 text-center text-xs text-slate-500">Nenhum alerta crítico no momento.</p>}</div></CardContent></Card><Card className="border-white/8 bg-slate-950/40 shadow-none"><CardContent className="p-5"><div className="flex items-center justify-between"><p className="text-sm font-medium text-white">Contas do período</p><CircleDollarSign size={17} className="text-cyan-200" /></div><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-xl bg-emerald-400/5 p-3"><p className="text-[10px] tracking-wider text-slate-500">A RECEBER</p><p className="mt-1 text-sm font-semibold text-emerald-100">{money(kpi?.receivablesCents)}</p></div><div className="rounded-xl bg-orange-400/5 p-3"><p className="text-[10px] tracking-wider text-slate-500">A PAGAR</p><p className="mt-1 text-sm font-semibold text-orange-100">{money(kpi?.payablesCents)}</p></div></div></CardContent></Card></div></div>
  <div className="mt-5 grid gap-5 xl:grid-cols-2"><Ranking title="Produtos mais vendidos" rows={data?.topSold ?? []} mode="quantity" /><Ranking title="Produtos mais lucrativos" rows={data?.topProfitable ?? []} mode="profit" /><Ranking title="Maior faturamento" rows={data?.topRevenue ?? []} mode="revenue" /><Ranking title="Melhor margem" rows={data?.topMargin ?? []} mode="margin" /><Ranking title="Maior giro em 90 dias" rows={data?.topTurnover ?? []} mode="turnover" /><Ranking title="Maior capital parado" rows={data?.topIdleValue ?? []} mode="idle" /></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><DecisionList title="O que comprar?" description="Recomendações por giro de 90 dias e saldo atual." rows={data?.recommendations ?? []} actionKey="suggestion" /><DecisionList title="Estoque parado" description="Capital imobilizado sem venda no período configurado." rows={data?.idleStock ?? []} actionKey="idle" /></div></>;
}

function DecisionList({ title, description, rows, actionKey }: { title: string; description: string; rows: any[]; actionKey: "suggestion" | "idle" }) { return <Card className="border-white/8 bg-slate-950/40 shadow-none"><CardContent className="p-5"><div className="flex items-start justify-between"><div><p className="text-sm font-medium text-white">{title}</p><p className="mt-1 text-xs text-slate-500">{description}</p></div><Badge className="border-white/8 bg-white/5 text-slate-400">DECISÃO</Badge></div>{rows.length ? <div className="mt-4 space-y-2">{rows.slice(0, 5).map((row: any) => <div key={row.id} className="flex items-center justify-between gap-3 rounded-xl bg-white/[.025] p-3"><div className="min-w-0"><p className="truncate text-xs font-medium text-white">{row.name}</p><p className="mt-1 text-[10px] text-slate-500">ABC {row.abcClass ?? "C"} • {row.stock} un. • {row.sold90} vendas/90d • {row.daysWithoutSale} dias sem venda</p></div>{actionKey === "suggestion" ? <Badge className={row.suggestion === "RECOMPRAR" ? "border-emerald-300/15 bg-emerald-300/10 text-emerald-100" : row.suggestion === "NÃO COMPRAR" ? "border-orange-300/15 bg-orange-300/10 text-orange-100" : "border-amber-300/15 bg-amber-300/10 text-amber-100"}>{row.suggestion}</Badge> : <span className="text-xs font-semibold text-orange-100">{money(row.idleValueCents)}</span>}</div>)}</div> : <p className="mt-4 rounded-xl border border-dashed border-white/8 p-5 text-center text-xs text-slate-500">Os dados aparecerão quando houver vendas e saldo de estoque.</p>}</CardContent></Card>; }

function Ranking({ title, rows, mode }: { title: string; rows: any[]; mode: "quantity" | "profit" | "revenue" | "margin" | "turnover" | "idle" }) { const value = (row: any) => mode === "quantity" ? `${row.quantity} un.` : mode === "profit" ? money(row.profit) : mode === "revenue" ? money(row.revenue) : mode === "margin" ? percent(row.marginBps) : mode === "turnover" ? `${row.sold90} un.` : money(row.idleValueCents); return <Card className="border-white/8 bg-slate-950/40 shadow-none"><CardContent className="p-5"><div className="mb-4 flex items-center justify-between"><p className="text-sm font-medium text-white">{title}</p><Badge className="border-white/8 bg-white/5 text-slate-400">TOP 10</Badge></div>{rows.length ? <div className="space-y-2">{rows.slice(0, 5).map((row, index) => <div className="flex items-center gap-3 rounded-xl bg-white/[.025] px-3 py-2.5" key={row.productId ?? row.id}><span className="grid size-6 place-items-center rounded-lg bg-white/5 text-xs font-bold text-cyan-200">{index + 1}</span><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium text-slate-200">{row.name}</p><p className="mt-0.5 text-[10px] text-slate-500">{row.code}</p></div><span className="text-xs font-semibold text-slate-100">{value(row)}</span></div>)}</div> : <p className="rounded-xl border border-dashed border-white/8 p-6 text-center text-xs text-slate-500">O ranking será construído com as próximas vendas.</p>}</CardContent></Card>; }

function ProductsPage({ products, suppliers, loading, onAdd, onArchive, onEdit, onAddStock, settings, canManage }: { products: Product[]; suppliers: any[]; loading: boolean; onAdd: () => void; onArchive: (id: number) => void; onEdit: (product: Product, changes: any) => void; onAddStock: (product: Product, quantity: string, cost: string) => void; settings: any; canManage: boolean }) { const [selected, setSelected] = useState<Product | null>(null); const [editing, setEditing] = useState<Product | null>(null); const [stockProduct, setStockProduct] = useState<Product | null>(null); const pricing = trpc.commerce.products.pricing.useQuery({ productId: selected?.id ?? 0 }, { enabled: Boolean(selected) }); return <><SectionHeading eyebrow="CATÁLOGO E SKU" title="Produtos em campo." description="Cadastre peças, acompanhe preço, disponibilidade e margem por SKU. Produtos com movimentação permanecem no histórico e podem ser inativados." action={canManage ? <Button onClick={onAdd} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200"><Plus size={16} />Adicionar produto</Button> : undefined} />{loading ? <div className="h-64 animate-pulse rounded-2xl bg-white/5" /> : products.length ? <div className="grid gap-4 md:grid-cols-2 2xl:grid-cols-3">{products.map(product => <button onClick={() => setSelected(product)} key={product.id} className="group rounded-2xl border border-white/8 bg-slate-950/40 p-4 text-left transition hover:-translate-y-0.5 hover:border-cyan-300/25 hover:bg-slate-950/55"><div className="flex gap-4"><div className="grid size-16 shrink-0 place-items-center rounded-xl bg-gradient-to-br from-teal-500/20 to-orange-400/10 text-cyan-200"><Store size={23} /></div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><p className="text-[10px] font-bold tracking-[.12em] text-cyan-300">{product.code}</p><h3 className="mt-1 truncate text-sm font-semibold text-white">{product.name}</h3></div><Badge className={product.status === "ativo" ? "border-emerald-300/15 bg-emerald-300/10 text-emerald-100" : "border-white/10 bg-white/5 text-slate-400"}>{product.status}</Badge></div><p className="mt-1.5 truncate text-xs text-slate-500">{[product.team, product.league, product.size].filter(Boolean).join(" • ") || "Sem atributos complementares"}</p></div></div><div className="mt-4 grid grid-cols-3 gap-2 border-t border-white/6 pt-3"><div><p className="text-[9px] tracking-wider text-slate-500">ESTOQUE</p><p className={`mt-1 text-sm font-semibold ${product.stock <= (settings?.minimumStock ?? 0) ? "text-orange-200" : "text-white"}`}>{product.stock} un.</p></div><div><p className="text-[9px] tracking-wider text-slate-500">PREÇO</p><p className="mt-1 text-sm font-semibold text-white">{money(product.listPriceCents)}</p></div><div><p className="text-[9px] tracking-wider text-slate-500">SITUAÇÃO</p><p className="mt-1 text-xs font-semibold text-cyan-100">{product.stock > 0 ? "DISPONÍVEL" : "ZERADO"}</p></div></div></button>)}</div> : <Empty title="Seu catálogo começa aqui" message="Adicione cada peça uma vez. O sistema atribui um código como COD001 e conecta preço, compras, estoque e vendas." icon={Store} action={canManage ? <Button onClick={onAdd} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200"><Plus size={15} />Cadastrar primeira peça</Button> : undefined} />}{selected && <Dialog open onOpenChange={open => !open && setSelected(null)}><DialogContent className="max-w-lg border-white/10 bg-slate-950 text-slate-100"><DialogHeader><DialogTitle className="font-display text-xl">{selected.name}</DialogTitle></DialogHeader><div className="grid grid-cols-2 gap-3 rounded-xl bg-white/[.035] p-4 text-sm"><div><p className="text-[10px] tracking-wider text-slate-500">CÓDIGO</p><p className="mt-1 font-medium text-cyan-200">{selected.code}</p></div><div><p className="text-[10px] tracking-wider text-slate-500">ESTOQUE</p><p className="mt-1 font-medium text-white">{selected.stock} unidades</p></div><div><p className="text-[10px] tracking-wider text-slate-500">PREÇO SUGERIDO</p><p className="mt-1 font-medium text-white">{money(pricing.data?.suggestedPriceCents)}</p></div><div><p className="text-[10px] tracking-wider text-slate-500">MARGEM ATUAL</p><p className="mt-1 font-medium text-white">{percent(pricing.data?.marginBps)}</p></div></div><div className="flex items-center justify-between rounded-xl border border-white/8 p-3"><StatusBadge status={pricing.data?.status ?? "SEM PREÇO"} /><span className="text-xs text-slate-400">Markup {pricing.data ? `${(pricing.data.markupBps / 100).toFixed(2)}x` : "—"}</span></div><div className="flex flex-wrap justify-end gap-2">{canManage && <Button variant="outline" onClick={() => setEditing(selected)} className="border-cyan-300/20 bg-cyan-300/5 text-cyan-100">Editar</Button>}{canManage && <Button variant="outline" onClick={() => setStockProduct(selected)} className="border-emerald-300/20 bg-emerald-300/5 text-emerald-100">+ Estoque</Button>}<Button variant="outline" onClick={() => setSelected(null)} className="border-white/10 bg-white/5 text-slate-200">Fechar</Button>{canManage && selected.status === "ativo" && <Button onClick={() => { onArchive(selected.id); setSelected(null); }} className="bg-orange-300 text-slate-950 hover:bg-orange-200">Inativar produto</Button>}</div></DialogContent></Dialog>}{editing && <ProductEditForm product={editing} suppliers={suppliers} onClose={() => setEditing(null)} onSave={onEdit} />}{stockProduct && <StockEntryForm product={stockProduct} onClose={() => setStockProduct(null)} onSave={onAddStock} />}</> }

function PricingPage({ products, settings }: { products: Product[]; settings: any }) {
  const [selectedId, setSelectedId] = useState<string>(products[0]?.id ? String(products[0].id) : "");
  const [promotionPrice, setPromotionPrice] = useState("");
  const selected = products.find(product => String(product.id) === selectedId);
  const pricing = trpc.commerce.products.pricing.useQuery({ productId: Number(selectedId) }, { enabled: Boolean(selectedId) });
  const preview = trpc.commerce.products.previewPricing.useQuery({ usdValueCents: selected?.usdValueCents ?? 0, quoteMicros: selected?.quoteMicros ?? 0, internationalShippingCents: selected?.internationalShippingCents ?? 0, domesticShippingCents: selected?.domesticShippingCents ?? 0, importFeesCents: selected?.importFeesCents ?? 0, packagingCostCents: selected?.packagingCostCents ?? 0, otherCostsCents: selected?.otherCostsCents ?? 0, salePriceCents: cents(promotionPrice || asInputValue(selected?.listPriceCents ?? 0)) }, { enabled: Boolean(selected) });
  const promotionalDiscount = selected && promotionPrice ? Math.max(0, selected.listPriceCents - cents(promotionPrice)) : 0;
  return <><SectionHeading eyebrow="MOTOR DE PRECIFICAÇÃO" title="Preço com precisão." description="O cálculo reflete dólar, fretes, taxas, embalagem, imposto e as margens configuradas. Nenhum preço é definido sem custo e resultado visíveis." />{products.length ? <div className="grid gap-5 xl:grid-cols-[.9fr_1.3fr]"><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><Label className="text-xs text-slate-400">Produto para análise</Label><Select value={selectedId} onValueChange={value => { setSelectedId(value); setPromotionPrice(""); }}><SelectTrigger className="mt-2 border-white/10 bg-white/5 text-white"><SelectValue placeholder="Selecione um produto" /></SelectTrigger><SelectContent>{products.map(product => <SelectItem key={product.id} value={String(product.id)}>{product.code} — {product.name}</SelectItem>)}</SelectContent></Select><div className="mt-6 space-y-3"><div className="flex justify-between text-sm"><span className="text-slate-500">Custo em dólar</span><span className="text-white">{money(selected?.usdValueCents)}</span></div><div className="flex justify-between text-sm"><span className="text-slate-500">Cotação utilizada</span><span className="text-white">R$ {((selected?.quoteMicros ?? 0) / 1_000_000).toFixed(2)}</span></div><div className="flex justify-between text-sm"><span className="text-slate-500">Preço de venda</span><span className="text-cyan-100">{money(selected?.listPriceCents)}</span></div></div><div className="mt-6 rounded-xl border border-orange-300/12 bg-orange-300/5 p-3 text-xs leading-5 text-orange-100">Mudanças na cotação afetam novas simulações. Compras e vendas já realizadas preservam o custo histórico da operação.</div></CardContent></Card><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-sm font-medium text-white">Diagnóstico de margem</p><p className="mt-1 text-xs text-slate-500">Parâmetros atuais: margem mínima {percent(settings?.minimumMarginBps)} e desejada {percent(settings?.desiredMarginBps)}.</p></div><StatusBadge status={pricing.data?.status ?? "SEM PREÇO"} /></div><div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{[["VALOR CONVERTIDO", money(pricing.data?.convertedCents)], ["CUSTO TOTAL", money(pricing.data?.totalCostCents)], ["PREÇO MÍNIMO", money(pricing.data?.minimumPriceCents)], ["PREÇO SUGERIDO", money(pricing.data?.suggestedPriceCents)], ["LUCRO BRUTO", money(pricing.data?.grossProfitCents)], ["MARKUP", pricing.data ? `${(pricing.data.markupBps / 100).toFixed(2)}x` : "—"]].map(([label, value]) => <div key={label} className="rounded-xl bg-white/[.035] p-4"><p className="text-[10px] tracking-[.1em] text-slate-500">{label}</p><p className="mt-2 text-lg font-semibold text-white">{value}</p></div>)}</div><div className="mt-5 rounded-xl bg-cyan-300/7 p-4"><p className="text-xs text-slate-400">Margem calculada</p><p className="mt-1 font-display text-3xl font-semibold text-cyan-100">{percent(pricing.data?.marginBps)}</p></div><div className="mt-5 rounded-xl border border-orange-300/12 bg-orange-300/[.045] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div className="flex-1"><Label>Simular preço promocional (R$)</Label><Input value={promotionPrice} onChange={event => setPromotionPrice(event.target.value)} inputMode="decimal" placeholder={asInputValue(selected?.listPriceCents ?? 0)} className="mt-2 border-orange-300/20 bg-slate-950/40 text-white" /></div><div className="sm:text-right"><p className="text-[10px] tracking-wider text-orange-100">DESCONTO SIMULADO</p><p className="mt-1 text-sm font-semibold text-orange-100">{money(promotionalDiscount)}</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><div><p className="text-[10px] text-slate-500">PREÇO PROMOCIONAL</p><p className="mt-1 text-sm font-semibold text-white">{money(cents(promotionPrice || asInputValue(selected?.listPriceCents ?? 0)))}</p></div><div><p className="text-[10px] text-slate-500">LUCRO SIMULADO</p><p className="mt-1 text-sm font-semibold text-cyan-100">{money(preview.data?.grossProfitCents)}</p></div><div><p className="text-[10px] text-slate-500">MARGEM SIMULADA</p><p className={`mt-1 text-sm font-semibold ${(preview.data?.marginBps ?? 0) < (settings?.minimumMarginBps ?? 0) ? "text-orange-100" : "text-emerald-100"}`}>{percent(preview.data?.marginBps)}</p></div></div><p className="mt-3 text-[10px] leading-4 text-slate-500">Esta é uma simulação. A confirmação de venda continua protegendo a margem mínima configurada.</p></div></CardContent></Card></div> : <Empty title="Cadastre um produto para precificar" message="Com a primeira peça no catálogo, a análise de custos e margem ficará disponível aqui." icon={CircleDollarSign} />}</>;
}

function QuickSale({ products, channels, methods, settings, onSubmit, pending }: { products: Product[]; channels: any[]; methods: any[]; settings: any; onSubmit: (input: any) => void; pending: boolean }) {
  const available = products.filter(product => product.status === "ativo" && product.stock > 0);
  const [productId, setProductId] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [price, setPrice] = useState("");
  const [discount, setDiscount] = useState("0");
  const [channelId, setChannelId] = useState("");
  const [methodId, setMethodId] = useState("");
  const [items, setItems] = useState<SaleItem[]>([]);
  const selected = available.find(product => String(product.id) === productId);
  const selectedPricing = trpc.commerce.products.pricing.useQuery({ productId: selected?.id ?? 0 }, { enabled: Boolean(selected) });
  const unitPriceCents = cents(price || asInputValue(selected?.listPriceCents ?? 0));
  const estimatedMarginBps = selectedPricing.data && unitPriceCents > 0 ? Math.round(((unitPriceCents - selectedPricing.data.totalCostCents) / unitPriceCents) * 10000) : undefined;
  const add = () => {
    if (!selected) return toast.error("Selecione um produto disponível.");
    const q = Math.max(1, Number(quantity) || 1);
    if (q > selected.stock) return toast.error("A quantidade informada supera o estoque disponível.");
    setItems(current => [...current.filter(item => item.productId !== selected.id), { productId: selected.id, quantity: q, unitPriceCents }]);
    setProductId("");
    setPrice("");
    setQuantity("1");
  };
  const grossTotal = items.reduce((sum, item) => sum + item.quantity * item.unitPriceCents, 0);
  const discountCents = Math.min(cents(discount), grossTotal);
  const total = grossTotal - discountCents;
  const selectedChannel = channels.find(channel => String(channel.id) === channelId);
  const selectedMethod = methods.find(method => String(method.id) === methodId);
  const channelFeeCents = Math.round(total * (selectedChannel?.feeBps ?? 0) / 10000);
  const paymentFeeCents = Math.round(total * (selectedMethod?.feeBps ?? 0) / 10000);
  const taxCents = Math.round(total * (settings?.salesTaxBps ?? 0) / 10000);
  const netReceivableCents = Math.max(0, total - channelFeeCents - paymentFeeCents);
  const paymentMethodName = methods.find(method => String(method.id) === methodId)?.name ?? "Não informado";
  const shareSale = () => {
    if (!items.length) return toast.error("Adicione ao menos uma peça antes de compartilhar.");
    const summary = `FEIRENSE — Resumo da venda\n\n${items.map(item => { const product = products.find(product => product.id === item.productId); const attributes = [product?.shirtType, product?.size].filter(Boolean).join(" • "); return `${item.quantity}x ${product?.name ?? "Produto"} (${product?.code ?? ""}${attributes ? ` — ${attributes}` : ""}) — ${money(item.quantity * item.unitPriceCents)}`; }).join("\n")}\n\nPagamento: ${paymentMethodName}\n${discountCents ? `Desconto: −${money(discountCents)}\n` : ""}Total: ${money(total)}`;
    if (navigator.share) {
      void navigator.share({ title: "Venda FEIRENSE", text: summary }).catch(error => {
        if (error?.name !== "AbortError") window.open(`https://wa.me/?text=${encodeURIComponent(summary)}`, "_blank", "noopener,noreferrer");
      });
      return;
    }
    window.open(`https://wa.me/?text=${encodeURIComponent(summary)}`, "_blank", "noopener,noreferrer");
  };
  return <><SectionHeading eyebrow="VENDA RÁPIDA • MOBILE FIRST" title="Venda em poucos toques." description="Escolha a peça, confira preço e margem, aplique desconto quando necessário e conclua sem perder o controle financeiro." />
    <div className="mb-4 grid grid-cols-[1fr_auto] items-center gap-4 rounded-2xl border border-cyan-300/12 bg-cyan-300/[.045] p-4 xl:hidden"><div><p className="text-[10px] font-semibold tracking-[.12em] text-cyan-100">RESUMO ATUAL</p><p className="mt-1 text-xs text-slate-400">{items.length} item(ns) • líquido estimado</p><p className="mt-1 font-display text-xl font-semibold text-white">{money(netReceivableCents)}</p></div><Badge className="border-cyan-300/15 bg-cyan-300/10 text-cyan-100">{discountCents ? `−${money(discountCents)}` : "SEM DESCONTO"}</Badge></div>
    <div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
      <Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5 sm:p-6"><p className="mb-5 text-sm font-medium text-white">Adicionar peça</p>{available.length ? <div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Label>Produto único, tamanho e tipo</Label><Select value={productId} onValueChange={value => { setProductId(value); const product = available.find(item => String(item.id) === value); setPrice(product ? asInputValue(product.listPriceCents) : ""); }}><SelectTrigger className="mt-2 border-white/10 bg-white/5 text-white"><SelectValue placeholder="Pesquisar por código, peça ou time" /></SelectTrigger><SelectContent>{available.map(product => <SelectItem key={product.id} value={String(product.id)}>{product.code} • {product.name} — {[product.shirtType, product.size].filter(Boolean).join(" • ") || "sem variação"} • {product.stock} un.</SelectItem>)}</SelectContent></Select></div><div><Label>Quantidade</Label><Input className="mt-2 border-white/10 bg-white/5 text-white" type="number" min="1" max={selected?.stock} value={quantity} onChange={event => setQuantity(event.target.value)} /></div><div><Label>Preço unitário (R$)</Label><Input className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" value={price} onChange={event => setPrice(event.target.value)} /></div>{selected && <div className="sm:col-span-2 rounded-xl border border-cyan-300/12 bg-cyan-300/[.045] p-3"><div className="flex items-center justify-between gap-3"><div><p className="text-[10px] tracking-[.12em] text-slate-500">MARGEM ESTIMADA</p><p className={`mt-1 text-sm font-semibold ${(estimatedMarginBps ?? 0) < 0 ? "text-orange-200" : "text-cyan-100"}`}>{selectedPricing.isLoading ? "Calculando..." : percent(estimatedMarginBps)}</p></div><div className="text-right"><p className="text-[10px] tracking-[.12em] text-slate-500">VARIAÇÃO DO CADASTRO</p><p className="mt-1 text-sm font-semibold text-white">{[selected.shirtType, selected.size].filter(Boolean).join(" • ") || "Produto único"}</p></div></div><p className="mt-2 text-[10px] leading-4 text-slate-500">A margem final considera taxas, imposto, desconto e custo histórico no momento da conclusão.</p></div>}<Button onClick={add} variant="outline" className="sm:col-span-2 border-cyan-300/20 bg-cyan-300/5 text-cyan-100 hover:bg-cyan-300/10">+ Adicionar à venda</Button></div> : <Empty title="Estoque indisponível" message="Registre uma compra para liberar produtos na venda rápida." icon={Box} />}</CardContent></Card>
      <Card className="border-white/8 bg-slate-950/50 xl:sticky xl:top-4 xl:self-start"><CardContent className="p-5 sm:p-6"><div className="flex justify-between"><div><p className="text-sm font-medium text-white">Resumo da venda</p><p className="mt-1 text-xs text-slate-500">{items.length} item(ns) selecionado(s)</p></div><ShoppingBag className="text-cyan-200" size={19} /></div>{items.length ? <div className="mt-5 space-y-2">{items.map(item => { const product = products.find(product => product.id === item.productId); return <div key={item.productId} className="flex items-center gap-3 rounded-xl bg-white/[.035] p-3"><div className="grid size-8 place-items-center rounded-lg bg-cyan-300/10 text-xs font-bold text-cyan-100">{item.quantity}x</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium text-white">{product?.name}</p><p className="mt-0.5 text-[10px] text-slate-500">{product?.code}</p></div><span className="text-xs font-semibold text-white">{money(item.unitPriceCents * item.quantity)}</span><button aria-label={`Remover ${product?.name ?? "item"}`} onClick={() => setItems(current => current.filter(currentItem => currentItem.productId !== item.productId))} className="text-slate-500 hover:text-orange-200">×</button></div>; })}</div> : <p className="mt-5 rounded-xl border border-dashed border-white/8 p-5 text-center text-xs text-slate-500">A seleção da venda aparece aqui.</p>}<div className="mt-5 grid gap-3 sm:grid-cols-2"><div><Label>Desconto total (R$)</Label><Input className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" value={discount} onChange={event => setDiscount(event.target.value)} /></div><div><Label>Canal de venda</Label><Select value={channelId} onValueChange={setChannelId}><SelectTrigger className="mt-2 border-white/10 bg-white/5 text-white"><SelectValue placeholder="Selecionar" /></SelectTrigger><SelectContent>{channels.map(channel => <SelectItem key={channel.id} value={String(channel.id)}>{channel.name} ({percent(channel.feeBps)})</SelectItem>)}</SelectContent></Select></div><div className="sm:col-span-2"><Label>Forma de pagamento</Label><Select value={methodId} onValueChange={setMethodId}><SelectTrigger className="mt-2 border-white/10 bg-white/5 text-white"><SelectValue placeholder="Selecionar" /></SelectTrigger><SelectContent>{methods.map(method => <SelectItem key={method.id} value={String(method.id)}>{method.name}</SelectItem>)}</SelectContent></Select></div></div><div className="mt-4 rounded-xl border border-cyan-300/10 bg-cyan-300/[.045] p-3"><div className="flex items-center justify-between"><p className="text-[10px] font-semibold tracking-[.12em] text-cyan-100">IMPACTO FINANCEIRO</p><p className="text-xs font-semibold text-cyan-100">A receber {money(netReceivableCents)}</p></div><div className="mt-3 grid grid-cols-3 gap-2"><div><p className="text-[9px] text-slate-500">CANAL</p><p className="mt-1 text-xs font-semibold text-slate-200">−{money(channelFeeCents)}</p></div><div><p className="text-[9px] text-slate-500">PAGAMENTO</p><p className="mt-1 text-xs font-semibold text-slate-200">−{money(paymentFeeCents)}</p></div><div><p className="text-[9px] text-slate-500">IMPOSTO (LUCRO)</p><p className="mt-1 text-xs font-semibold text-slate-200">−{money(taxCents)}</p></div></div></div><div className="mt-5 flex items-end justify-between border-t border-white/8 pt-4"><div><p className="text-[10px] tracking-[.14em] text-slate-500">TOTAL DA VENDA</p><p className="mt-1 font-display text-2xl font-semibold text-white">{money(total)}</p>{discountCents > 0 && <p className="mt-1 text-[10px] text-orange-200">Desconto aplicado: −{money(discountCents)}</p>}</div><div className="flex flex-col gap-2 sm:flex-row"><Button variant="outline" disabled={!items.length} onClick={shareSale} className="border-emerald-300/20 bg-emerald-300/5 text-emerald-100 hover:bg-emerald-300/10"><Share2 size={15} />Compartilhar</Button><Button disabled={!items.length || pending} onClick={() => onSubmit({ soldAt: new Date(), saleChannelId: channelId ? Number(channelId) : undefined, paymentMethodId: methodId ? Number(methodId) : undefined, items, discountCents, paymentStatus: "recebido" })} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">{pending ? "Registrando..." : "Concluir venda"}</Button></div></div></CardContent></Card>
    </div></>;
}

function PurchasePage({ products, suppliers, methods, onSubmit, pending }: { products: Product[]; suppliers: any[]; methods: any[]; onSubmit: (input: any) => void; pending: boolean }) { const [productId, setProductId] = useState(""); const [supplierId, setSupplierId] = useState(""); const [quantity, setQuantity] = useState("1"); const [cost, setCost] = useState(""); const [orderNumber, setOrderNumber] = useState(""); const selected = products.find(product => String(product.id) === productId); return <><SectionHeading eyebrow="ENTRADA DE MERCADORIA" title="Compras com custo preservado." description="Cada lote cria seu próprio custo histórico. Assim, uma compra nova não recalcula a margem de vendas anteriores." />{products.length ? <Card className="max-w-3xl border-white/8 bg-slate-950/40"><CardContent className="p-5 sm:p-6"><div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Label>Produto</Label><Select value={productId} onValueChange={value => { setProductId(value); const product = products.find(item => String(item.id) === value); if (product) setCost(asInputValue(product.listPriceCents)); }}><SelectTrigger className="mt-2 border-white/10 bg-white/5 text-white"><SelectValue placeholder="Selecione a peça comprada" /></SelectTrigger><SelectContent>{products.map(product => <SelectItem key={product.id} value={String(product.id)}>{product.code} — {product.name}</SelectItem>)}</SelectContent></Select></div><div><Label>Fornecedor</Label><Select value={supplierId} onValueChange={setSupplierId}><SelectTrigger className="mt-2 border-white/10 bg-white/5 text-white"><SelectValue placeholder="Opcional" /></SelectTrigger><SelectContent>{suppliers.map(supplier => <SelectItem key={supplier.id} value={String(supplier.id)}>{supplier.name}</SelectItem>)}</SelectContent></Select></div><div><Label>Número do pedido</Label><Input className="mt-2 border-white/10 bg-white/5 text-white" value={orderNumber} onChange={event => setOrderNumber(event.target.value)} placeholder="Ex.: 2026-041" /></div><div><Label>Quantidade</Label><Input className="mt-2 border-white/10 bg-white/5 text-white" type="number" min="1" value={quantity} onChange={event => setQuantity(event.target.value)} /></div><div><Label>Custo unitário (R$)</Label><Input className="mt-2 border-white/10 bg-white/5 text-white" value={cost} onChange={event => setCost(event.target.value)} inputMode="decimal" /></div></div><div className="mt-6 flex items-center justify-between rounded-xl bg-cyan-300/6 p-4"><div><p className="text-[10px] tracking-wider text-slate-500">TOTAL DO LOTE</p><p className="mt-1 font-display text-xl font-semibold text-cyan-100">{money((Number(quantity) || 0) * cents(cost))}</p></div><Button disabled={!selected || pending} onClick={() => selected && onSubmit({ supplierId: supplierId ? Number(supplierId) : undefined, purchaseDate: new Date(), orderNumber, paymentStatus: "pendente", items: [{ productId: selected.id, quantity: Math.max(1, Number(quantity)), unitCostCents: cents(cost) }] })} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">{pending ? "Registrando..." : "Registrar compra"}</Button></div></CardContent></Card> : <Empty title="Cadastre uma peça antes" message="A compra precisa estar vinculada a um produto para criar estoque e preservar o custo do lote." icon={PackagePlus} />}</> }

function InventoryPage({ products, dashboard, loading, onNavigate }: { products: Product[]; dashboard: any; loading: boolean; onNavigate: (view: AppView) => void }) { const available = products.filter(product => product.stock > 0).length; const low = products.filter(product => product.stock > 0 && product.stock <= 2).length; const health = dashboard?.inventoryHealth ?? []; if (loading) return <div className="h-64 animate-pulse rounded-2xl bg-white/5" />; return <><SectionHeading eyebrow="ESTOQUE POR MOVIMENTAÇÃO" title="O que está pronto para vender." description="Saldo é calculado a partir de compras, vendas, devoluções e ajustes. Não existe edição manual de quantidade sem rastreabilidade." action={<Button onClick={() => onNavigate("compras")} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200"><PackagePlus size={15} />Registrar compra</Button>} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><Metric title="EM ESTOQUE" value={`${available} SKUs`} note="Produtos com saldo positivo" icon={Box} /><Metric title="ESTOQUE BAIXO" value={`${low} SKUs`} note="Precisam de reposição" tone="orange" icon={AlertTriangle} /><Metric title="SEM ESTOQUE" value={`${products.filter(product => product.stock <= 0).length} SKUs`} note="Não disponíveis para venda" tone="violet" icon={PackagePlus} /></div>{health.length > 0 && <Card className="mb-5 border-white/8 bg-slate-950/40"><CardContent className="p-5"><div className="flex items-center justify-between"><div><p className="text-sm font-medium text-white">Saúde e giro do estoque</p><p className="mt-1 text-xs text-slate-500">Classe ABC, saída recente, capital parado e prioridade de reposição.</p></div><Badge className="border-cyan-300/15 bg-cyan-300/10 text-cyan-100">ANÁLISE</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{health.filter((row: any) => row.stock > 0).sort((a: any, b: any) => b.idleValueCents - a.idleValueCents).slice(0, 6).map((row: any) => <div key={row.id} className="rounded-xl bg-white/[.025] p-3"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-xs font-medium text-white">{row.name}</p><p className="mt-1 text-[10px] text-slate-500">{row.code} • ABC {row.abcClass}</p></div><Badge className={row.classification === "Encalhado" ? "border-orange-300/15 bg-orange-300/10 text-orange-100" : row.classification === "Alta saída" ? "border-emerald-300/15 bg-emerald-300/10 text-emerald-100" : "border-white/8 bg-white/5 text-slate-300"}>{row.classification}</Badge></div><div className="mt-3 grid grid-cols-3 gap-2"><div><p className="text-[9px] text-slate-500">GIRO 90D</p><p className="mt-1 text-xs font-semibold text-cyan-100">{row.sold90} un.</p></div><div><p className="text-[9px] text-slate-500">PARADO</p><p className="mt-1 text-xs font-semibold text-slate-200">{row.daysWithoutSale}d</p></div><div><p className="text-[9px] text-slate-500">IMOBILIZADO</p><p className="mt-1 text-xs font-semibold text-orange-100">{money(row.idleValueCents)}</p></div></div></div>)}</div></CardContent></Card>}{products.length ? <div className="overflow-hidden rounded-2xl border border-white/8 bg-slate-950/40"><div className="hidden grid-cols-[1.5fr_.8fr_.7fr_.7fr] gap-4 border-b border-white/8 px-5 py-3 text-[10px] font-bold tracking-[.12em] text-slate-500 md:grid"><span>PRODUTO</span><span>SALDO</span><span>PREÇO</span><span>SITUAÇÃO</span></div>{products.map(product => <div key={product.id} className="grid gap-3 border-b border-white/[.055] px-5 py-4 last:border-0 md:grid-cols-[1.5fr_.8fr_.7fr_.7fr] md:items-center"><div><p className="text-xs font-medium text-white">{product.name}</p><p className="mt-1 text-[10px] tracking-wider text-cyan-300">{product.code} • {product.size || "sem tamanho"}</p></div><p className={`text-sm font-semibold ${product.stock <= 0 ? "text-orange-200" : product.stock <= 2 ? "text-amber-100" : "text-slate-100"}`}>{product.stock} un.</p><p className="text-sm text-slate-300">{money(product.listPriceCents)}</p><Badge className={product.stock <= 0 ? "w-fit border-orange-300/15 bg-orange-300/10 text-orange-100" : product.stock <= 2 ? "w-fit border-amber-300/15 bg-amber-300/10 text-amber-100" : "w-fit border-emerald-300/15 bg-emerald-300/10 text-emerald-100"}>{product.stock <= 0 ? "ZERADO" : product.stock <= 2 ? "BAIXO" : "DISPONÍVEL"}</Badge></div>)}</div> : <Empty title="Sem movimentações de estoque" message="Registre uma compra para começar a acompanhar saldos e alertas de reposição." icon={Box} />}</> }

function ExpensesPage({ rows, onSubmit, pending }: { rows: any[]; onSubmit: (input: any) => void; pending: boolean }) { const [description, setDescription] = useState(""); const [category, setCategory] = useState("Anúncios/Marketing"); const [amount, setAmount] = useState(""); return <><SectionHeading eyebrow="CUSTOS OPERACIONAIS" title="Despesas sob controle." description="Registre tudo que reduz o lucro líquido: marketing, impostos, embalagem, aluguel e demais compromissos." /><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><p className="text-sm font-medium text-white">Nova despesa</p><div className="mt-5 space-y-4"><div><Label>Descrição</Label><Input value={description} onChange={event => setDescription(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" placeholder="Ex.: Campanha de tráfego" /></div><div><Label>Categoria</Label><Input value={category} onChange={event => setCategory(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" /></div><div><Label>Valor (R$)</Label><Input value={amount} onChange={event => setAmount(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" placeholder="0,00" /></div><Button disabled={!description || !cents(amount) || pending} onClick={() => onSubmit({ expenseDate: new Date(), category, description, amountCents: cents(amount), status: "pendente" })} className="w-full bg-orange-300 text-slate-950 hover:bg-orange-200">{pending ? "Registrando..." : "Lançar despesa"}</Button></div></CardContent></Card><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><div className="flex justify-between"><div><p className="text-sm font-medium text-white">Lançamentos recentes</p><p className="mt-1 text-xs text-slate-500">Contas pendentes e pagas.</p></div><ReceiptText className="text-orange-200" size={18} /></div>{rows.length ? <div className="mt-4 space-y-2">{rows.slice(0, 8).map(row => <div key={row.id} className="flex items-center justify-between rounded-xl bg-white/[.025] p-3"><div><p className="text-xs font-medium text-white">{row.description}</p><p className="mt-1 text-[10px] text-slate-500">{row.category} • {new Date(row.expenseDate).toLocaleDateString("pt-BR")}</p></div><div className="text-right"><p className="text-xs font-semibold text-orange-100">{money(row.amountCents)}</p><Badge className="mt-1 border-white/8 bg-white/5 text-[9px] text-slate-400">{row.status.toUpperCase()}</Badge></div></div>)}</div> : <Empty title="Nenhuma despesa registrada" message="Comece pelo primeiro custo operacional para enxergar o lucro líquido real." icon={ReceiptText} />}</CardContent></Card></div></> }

function FinancialPage({ dashboard, sales, expenses, cashflow }: { dashboard: any; sales: any[]; expenses: any[]; cashflow: any }) {
  const kpi = dashboard?.kpis;
  const summary = cashflow?.summary;
  return <><SectionHeading eyebrow="FLUXO E RESULTADO" title="Financeiro, sem ruído." description="Diferencie resultado econômico de dinheiro efetivamente recebido para tomar decisões com uma visão clara da operação." />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
      <Metric title="FATURAMENTO" value={money(kpi?.revenueCents)} note="Vendas do mês, já com descontos" icon={TrendingUp} />
      <Metric title="RECEBIMENTOS" value={money(summary?.inflowsCents)} note="Entradas já liquidadas" tone="emerald" icon={ArrowUpRight} />
      <Metric title="CUSTO DAS VENDAS" value={money(kpi?.salesCostCents)} note="Custo histórico dos lotes vendidos" tone="orange" icon={Box} />
      <Metric title="DESPESAS" value={money(kpi?.expenseCents)} note="Custos operacionais do mês" tone="orange" icon={ReceiptText} />
      <Metric title="LUCRO BRUTO" value={money(kpi?.grossProfitCents)} note="Após custos, taxas e impostos" tone="violet" icon={Sparkles} />
      <Metric title="LUCRO LÍQUIDO" value={money(kpi?.netProfitCents)} note={`Margem líquida ${percent(kpi?.marginBps)}`} tone="emerald" icon={Target} />
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[.95fr_1.05fr]"><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><p className="text-sm font-medium text-white">Posição de caixa</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-emerald-400/5 p-4"><p className="text-[10px] tracking-wider text-slate-500">A RECEBER</p><p className="mt-1 text-lg font-semibold text-emerald-100">{money(summary?.receivablesCents)}</p></div><div className="rounded-xl bg-orange-400/5 p-4"><p className="text-[10px] tracking-wider text-slate-500">A PAGAR</p><p className="mt-1 text-lg font-semibold text-orange-100">{money(summary?.payablesCents)}</p></div><div className="rounded-xl bg-cyan-400/5 p-4"><p className="text-[10px] tracking-wider text-slate-500">SALDO REALIZADO</p><p className="mt-1 text-lg font-semibold text-cyan-100">{money(summary?.balanceCents)}</p></div><div className="rounded-xl bg-violet-400/5 p-4"><p className="text-[10px] tracking-wider text-slate-500">SALDO PROJETADO</p><p className="mt-1 text-lg font-semibold text-violet-100">{money(summary?.projectedBalanceCents)}</p></div></div><p className="mt-5 text-xs leading-5 text-slate-500">Faturamento e lucro medem desempenho econômico. O caixa mostra somente entradas e saídas efetivamente liquidadas, além dos compromissos já previstos.</p></CardContent></Card><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><div className="flex items-center justify-between"><p className="text-sm font-medium text-white">Lançamentos recentes</p><Badge className="border-white/8 bg-white/5 text-slate-400">FLUXO</Badge></div>{cashflow?.entries?.length ? <div className="mt-4 space-y-2">{cashflow.entries.slice(0, 6).map((entry: any) => <div key={entry.id} className="flex items-center justify-between rounded-xl bg-white/[.025] p-3"><div><p className="text-xs font-medium text-white">{entry.description}</p><p className="mt-1 text-[10px] text-slate-500">{entry.kind === "receber" ? "Entrada" : "Saída"} • {entry.status.toUpperCase()}</p></div><span className={`text-xs font-semibold ${entry.kind === "receber" ? "text-emerald-100" : "text-orange-100"}`}>{entry.kind === "receber" ? "+" : "−"}{money(entry.amountCents)}</span></div>)}</div> : <p className="mt-4 rounded-xl border border-dashed border-white/8 p-6 text-center text-xs text-slate-500">Os lançamentos aparecem quando compras, vendas e despesas são registradas.</p>}</CardContent></Card></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><p className="text-sm font-medium text-white">Contas a receber</p><div className="mt-4 space-y-2">{sales.filter(sale => sale.paymentStatus === "pendente").length ? sales.filter(sale => sale.paymentStatus === "pendente").map(sale => <div key={sale.id} className="flex justify-between rounded-xl bg-white/[.025] p-3"><span className="text-xs text-slate-300">{sale.saleNumber}</span><span className="text-xs font-semibold text-emerald-100">{money(sale.netCents)}</span></div>) : <p className="rounded-xl border border-dashed border-white/8 p-6 text-center text-xs text-slate-500">Nenhuma venda pendente.</p>}</div></CardContent></Card><Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><p className="text-sm font-medium text-white">Contas a pagar</p><div className="mt-4 space-y-2">{expenses.filter(expense => expense.status === "pendente" || expense.status === "vencido").length ? expenses.filter(expense => expense.status === "pendente" || expense.status === "vencido").map(expense => <div key={expense.id} className="flex justify-between rounded-xl bg-white/[.025] p-3"><span className="text-xs text-slate-300">{expense.description}</span><span className="text-xs font-semibold text-orange-100">{money(expense.amountCents)}</span></div>) : <p className="rounded-xl border border-dashed border-white/8 p-6 text-center text-xs text-slate-500">Nenhuma conta pendente.</p>}</div></CardContent></Card></div></>;
}

function ReportsPage({ products, dashboard, months, onMonthsChange, onExport, onPrint }: { products: Product[]; dashboard: any; months: string; onMonthsChange: (months: string) => void; onExport: () => void; onPrint: () => void }) {
  const kpi = dashboard?.kpis;
  const financialRows = [["Faturamento", money(kpi?.revenueCents), "Receita líquida de descontos"], ["Custo das vendas", money(kpi?.salesCostCents), "Custo histórico dos lotes vendidos"], ["Despesas", money(kpi?.expenseCents), "Custos operacionais do mês"], ["Lucro bruto", money(kpi?.grossProfitCents), "Após custos, taxas e impostos"], ["Lucro líquido", money(kpi?.netProfitCents), "Resultado após despesas"]];
  return <><SectionHeading eyebrow="ANÁLISE E EXPORTAÇÃO" title="Relatórios que orientam." description="Filtre o período de análise e consolide resultado financeiro, estoque e desempenho comercial para decisões mais objetivas." action={<div className="flex flex-wrap gap-2"><Select value={months} onValueChange={onMonthsChange}><SelectTrigger aria-label="Período do relatório" className="h-10 w-[130px] border-white/10 bg-white/5 text-slate-200"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="3">3 meses</SelectItem><SelectItem value="6">6 meses</SelectItem><SelectItem value="12">12 meses</SelectItem></SelectContent></Select><Button variant="outline" onClick={onPrint} className="border-white/10 bg-white/5 text-slate-200"><ReceiptText size={15} />Gerar PDF</Button><Button onClick={onExport} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200"><Download size={15} />Excel (CSV)</Button></div>} /><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-4"><Metric title="FATURAMENTO" value={money(kpi?.revenueCents)} note="Vendas líquidas de descontos" icon={TrendingUp} /><Metric title="LUCRO LÍQUIDO" value={money(kpi?.netProfitCents)} note={`Margem ${percent(kpi?.marginBps)}`} tone="emerald" icon={Sparkles} /><Metric title="CUSTOS + DESPESAS" value={money((kpi?.salesCostCents ?? 0) + (kpi?.expenseCents ?? 0))} note="Operação do mês" tone="orange" icon={ReceiptText} /><Metric title="VALOR EM ESTOQUE" value={money(kpi?.stockValueCents)} note={`${kpi?.stockUnits ?? 0} peças disponíveis`} tone="violet" icon={Box} /><Metric title="PRODUTOS ATIVOS" value={`${products.filter(product => product.status === "ativo").length}`} note="SKUs disponíveis no catálogo" icon={Store} /><Metric title="SELL-THROUGH" value={dashboard?.kpis?.stockUnits + dashboard?.kpis?.piecesSold ? percent(Math.round((dashboard.kpis.piecesSold * 10000) / (dashboard.kpis.stockUnits + dashboard.kpis.piecesSold))) : "0,0%"} note="Peças vendidas versus movimentadas" tone="emerald" icon={TrendingUp} /><Metric title="TICKET MÉDIO" value={money(kpi?.ticketCents)} note={`${kpi?.piecesSold ?? 0} peças vendidas`} tone="cyan" icon={Target} /><Metric title="META DE LUCRO" value={dashboard?.kpis?.profitGoalCents ? `${Math.round((dashboard.kpis.netProfitCents / dashboard.kpis.profitGoalCents) * 100)}%` : "—"} note="Progresso do mês" tone="orange" icon={Target} /></div><div className="mt-5 grid gap-5 xl:grid-cols-3"><Card className="border-white/8 bg-slate-950/40 xl:col-span-1"><CardContent className="p-5"><p className="text-sm font-medium text-white">Consolidado financeiro</p><div className="mt-4 space-y-2">{financialRows.map(([label, value, note]) => <div key={label} className="flex items-center justify-between rounded-xl bg-white/[.025] p-3"><div><p className="text-xs font-medium text-slate-200">{label}</p><p className="mt-1 text-[10px] text-slate-500">{note}</p></div><p className="text-xs font-semibold text-cyan-100">{value}</p></div>)}</div></CardContent></Card><div className="grid gap-5 md:grid-cols-2 xl:col-span-2"><Ranking title="Mais vendidos" rows={dashboard?.topSold ?? []} mode="quantity" /><Ranking title="Maior faturamento" rows={dashboard?.topRevenue ?? []} mode="revenue" /><Ranking title="Maior giro" rows={dashboard?.topTurnover ?? []} mode="turnover" /><Ranking title="Capital parado" rows={dashboard?.topIdleValue ?? []} mode="idle" /></div></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><DecisionList title="Recomendações de reposição" description="Prioridade de compra por giro, saldo e classe ABC." rows={dashboard?.recommendations ?? []} actionKey="suggestion" /><DecisionList title="Estoque parado" description="Produtos sem venda e valor imobilizado no período." rows={dashboard?.idleStock ?? []} actionKey="idle" /></div><Card className="mt-5 border-white/8 bg-slate-950/40"><CardContent className="p-5"><p className="text-sm font-medium text-white">Relatório gerencial mensal</p><p className="mt-2 text-xs leading-5 text-slate-500">A visão reúne resultado financeiro, rankings comerciais, giro, estoque parado e recomendações para o período selecionado. Use <strong>Gerar PDF</strong> para salvar ou imprimir a visão filtrada; o arquivo CSV abre diretamente no Excel e em outras planilhas.</p></CardContent></Card></>;
}

function DirectoryPage({ type, rows, onSubmit, pending, canManage }: { type: "clientes" | "fornecedores"; rows: any[]; onSubmit: (input: any) => void; pending: boolean; canManage: boolean }) {
  const isCustomer = type === "clientes";
  const [editing, setEditing] = useState<any | null>(null);
  const [open, setOpen] = useState(false);
  const startCreate = () => { setEditing(null); setOpen(true); };
  return <><SectionHeading eyebrow={isCustomer ? "RELACIONAMENTO" : "REDE DE FORNECIMENTO"} title={isCustomer ? "Clientes." : "Fornecedores."} description={isCustomer ? "Acompanhe relacionamento, compras, ticket e recorrência em cada contato." : "Centralize parceiros, origem das peças e dados de compra."} action={canManage ? <Button onClick={startCreate} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200"><Plus size={15} />{isCustomer ? "Novo cliente" : "Novo fornecedor"}</Button> : undefined} />{rows.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{rows.map(row => <Card key={row.id} className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><div className="flex justify-between"><div className="grid size-10 place-items-center rounded-xl bg-cyan-300/10 text-cyan-100"><Users size={18} /></div><Badge className="border-white/8 bg-white/5 text-slate-400">{isCustomer ? (row.classification || row.status || "novo") : "ATIVO"}</Badge></div><p className="mt-4 text-sm font-semibold text-white">{row.name}</p><p className="mt-1 text-xs text-slate-500">{row.whatsapp || row.company || row.country || "Sem dados adicionais"}</p>{isCustomer && <div className="mt-4 grid grid-cols-3 gap-2 border-t border-white/6 pt-3"><div><p className="text-[9px] text-slate-500">COMPRAS</p><p className="mt-1 text-xs font-semibold text-white">{row.purchaseCount ?? 0}</p></div><div><p className="text-[9px] text-slate-500">TICKET</p><p className="mt-1 text-xs font-semibold text-cyan-100">{money(row.ticketCents)}</p></div><div><p className="text-[9px] text-slate-500">ÚLTIMA</p><p className="mt-1 text-xs font-semibold text-slate-200">{row.lastPurchase ? new Date(row.lastPurchase).toLocaleDateString("pt-BR") : "—"}</p></div></div>}{canManage && <Button variant="outline" onClick={() => { setEditing(row); setOpen(true); }} className="mt-4 w-full border-white/10 bg-white/5 text-slate-200">Editar cadastro</Button>}</CardContent></Card>)}</div> : <Empty title={isCustomer ? "Nenhum cliente cadastrado" : "Nenhum fornecedor cadastrado"} message={isCustomer ? "Cadastre clientes para organizar o relacionamento e acompanhar sua recorrência." : "Cadastre fornecedores para vinculá-los a produtos e compras."} icon={Users} action={canManage ? <Button onClick={startCreate} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">Criar cadastro</Button> : undefined} />}{open && <DirectoryForm type={type} row={editing} pending={pending} onClose={() => setOpen(false)} onSave={input => { onSubmit(input); setOpen(false); }} />}</>;
}

function DirectoryForm({ type, row, onClose, onSave, pending }: { type: "clientes" | "fornecedores"; row: any | null; onClose: () => void; onSave: (input: any) => void; pending: boolean }) {
  const isCustomer = type === "clientes"; const [name, setName] = useState(row?.name || ""); const [whatsapp, setWhatsapp] = useState(row?.whatsapp || ""); const [city, setCity] = useState(row?.city || ""); const [notes, setNotes] = useState(row?.notes || ""); const [company, setCompany] = useState(row?.company || ""); const [country, setCountry] = useState(row?.country || ""); const [sourceUrl, setSourceUrl] = useState(row?.sourceUrl || ""); const [instagram, setInstagram] = useState(row?.instagram || ""); const [email, setEmail] = useState(row?.email || "");
  const inputClass = "mt-2 border-white/10 bg-white/5 text-white";
  const submit = () => { if (!name.trim()) return toast.error("Informe o nome."); if (sourceUrl && !/^https?:\/\//i.test(sourceUrl)) return toast.error("Informe uma URL válida iniciando com http:// ou https://."); if (isCustomer) onSave({ id: row?.id, name, whatsapp, instagram, email, city, notes }); else onSave({ id: row?.id, name, company, whatsapp, country, city, sourceUrl, notes }); };
  return <Dialog open onOpenChange={value => !value && onClose()}><DialogContent className="border-white/10 bg-slate-950 text-slate-100 sm:max-w-lg"><DialogHeader><DialogTitle>{row ? "Editar" : "Novo"} {isCustomer ? "cliente" : "fornecedor"}</DialogTitle></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Label>Nome</Label><Input aria-label="Nome" value={name} onChange={event => setName(event.target.value)} className={inputClass} /></div>{isCustomer ? <><div><Label>WhatsApp</Label><Input aria-label="WhatsApp" value={whatsapp} onChange={event => setWhatsapp(event.target.value)} className={inputClass} /></div><div><Label>Instagram</Label><Input aria-label="Instagram" value={instagram} onChange={event => setInstagram(event.target.value)} className={inputClass} /></div><div><Label>E-mail</Label><Input aria-label="E-mail" type="email" value={email} onChange={event => setEmail(event.target.value)} className={inputClass} /></div><div><Label>Cidade</Label><Input aria-label="Cidade" value={city} onChange={event => setCity(event.target.value)} className={inputClass} /></div></> : <><div><Label>Empresa</Label><Input aria-label="Empresa" value={company} onChange={event => setCompany(event.target.value)} className={inputClass} /></div><div><Label>WhatsApp</Label><Input aria-label="WhatsApp" value={whatsapp} onChange={event => setWhatsapp(event.target.value)} className={inputClass} /></div><div><Label>País</Label><Input aria-label="País" value={country} onChange={event => setCountry(event.target.value)} className={inputClass} /></div><div><Label>Cidade</Label><Input aria-label="Cidade" value={city} onChange={event => setCity(event.target.value)} className={inputClass} /></div><div className="sm:col-span-2"><Label>URL de origem</Label><Input aria-label="URL de origem" type="url" value={sourceUrl} onChange={event => setSourceUrl(event.target.value)} placeholder="https://" className={inputClass} /></div></>}<div className="sm:col-span-2"><Label>Observações</Label><Textarea aria-label="Observações" value={notes} onChange={event => setNotes(event.target.value)} className={inputClass} /></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={onClose} className="border-white/10 bg-white/5 text-white">Cancelar</Button><Button disabled={pending} onClick={submit} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">{pending ? "Salvando..." : "Salvar cadastro"}</Button></div></DialogContent></Dialog>;
}

function AdvancedSettingsPage({ settings, channels, methods, onSubmit, onSaveChannel, onSaveMethod, pending }: { settings: any; channels: any[]; methods: any[]; onSubmit: (input: any) => void; onSaveChannel: (input: any) => void; onSaveMethod: (input: any) => void; pending: boolean }) { return <><SettingsPage settings={settings} onSubmit={onSubmit} pending={pending} /><div className="mt-6 grid gap-5 xl:grid-cols-2"><CommercialOptionManager title="Canais de venda" description="Taxas aplicadas automaticamente à venda." rows={channels} onSave={onSaveChannel} pending={pending} /><CommercialOptionManager title="Formas de pagamento" description="Taxas por meio de recebimento." rows={methods} onSave={onSaveMethod} pending={pending} /></div></>; }

function CommercialOptionManager({ title, description, rows, onSave, pending }: { title: string; description: string; rows: any[]; onSave: (input: any) => void; pending: boolean }) { const [name, setName] = useState(""); const [fee, setFee] = useState("0"); const [editing, setEditing] = useState<number | null>(null); const begin = (row?: any) => { setEditing(row?.id ?? null); setName(row?.name ?? ""); setFee(row ? (row.feeBps / 100).toFixed(2) : "0"); }; const save = () => { if (!name.trim()) return toast.error("Informe o nome."); onSave({ id: editing ?? undefined, name, feeBps: Math.round(Number(fee.replace(",", ".")) * 100), active: true }); begin(); }; return <Card className="border-white/8 bg-slate-950/40"><CardContent className="p-5"><div><p className="text-sm font-medium text-white">{title}</p><p className="mt-1 text-xs text-slate-500">{description}</p></div><div className="mt-4 space-y-2">{rows.length ? rows.map(row => <button key={row.id} onClick={() => begin(row)} className="flex w-full items-center justify-between rounded-xl bg-white/[.03] p-3 text-left hover:bg-white/[.06]"><span className="text-xs font-medium text-slate-200">{row.name}</span><span className="text-xs text-cyan-100">{percent(row.feeBps)}</span></button>) : <p className="rounded-xl border border-dashed border-white/8 p-4 text-center text-xs text-slate-500">Nenhum item cadastrado.</p>}</div><div className="mt-5 grid gap-3 sm:grid-cols-[1fr_.55fr_auto]"><Input value={name} onChange={event => setName(event.target.value)} placeholder="Nome" className="border-white/10 bg-white/5 text-white" /><Input value={fee} onChange={event => setFee(event.target.value)} inputMode="decimal" placeholder="Taxa (%)" className="border-white/10 bg-white/5 text-white" /><Button disabled={pending} onClick={save} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">{editing ? "Atualizar" : "Adicionar"}</Button></div></CardContent></Card>; }

function SettingsPage({ settings, onSubmit, pending }: { settings: any; onSubmit: (input: any) => void; pending: boolean }) { const [quote, setQuote] = useState(""); const [minMargin, setMinMargin] = useState(""); const [desiredMargin, setDesiredMargin] = useState(""); const [tax, setTax] = useState(""); const [stock, setStock] = useState(""); const [unitsGoal, setUnitsGoal] = useState(""); const initialize = () => { if (!quote && settings) { setQuote(((settings.dollarQuoteMicros ?? 0) / 1000000).toFixed(2)); setMinMargin(((settings.minimumMarginBps ?? 0) / 100).toFixed(0)); setDesiredMargin(((settings.desiredMarginBps ?? 0) / 100).toFixed(0)); setTax(((settings.salesTaxBps ?? 0) / 100).toFixed(0)); setStock(String(settings.minimumStock ?? 2)); setUnitsGoal(String(settings.unitsGoal ?? 0)); } }; useMemo(initialize, [settings]); const submit = () => settings && onSubmit({ dollarQuoteMicros: Math.round(Number(quote.replace(",", ".")) * 1000000), minimumMarginBps: Math.round(Number(minMargin) * 100), desiredMarginBps: Math.round(Number(desiredMargin) * 100), salesTaxBps: Math.round(Number(tax) * 100), packagingCostCents: settings.packagingCostCents, reserveBps: settings.reserveBps, revenueGoalCents: settings.revenueGoalCents, profitGoalCents: settings.profitGoalCents, unitsGoal: Number(unitsGoal) || 0, minimumStock: Number(stock), idleDaysThreshold: settings.idleDaysThreshold }); return <><SectionHeading eyebrow="PARÂMETROS DA OPERAÇÃO" title="Configurações centrais." description="As regras abaixo alimentam precificação, alertas, metas e cálculos de todas as operações novas." /><Card className="max-w-4xl border-white/8 bg-slate-950/40"><CardContent className="p-5 sm:p-6"><div className="grid gap-5 sm:grid-cols-2"><div><Label>Cotação atual do dólar (R$)</Label><Input value={quote} onChange={event => setQuote(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" /></div><div><Label>Estoque mínimo (unidades)</Label><Input value={stock} onChange={event => setStock(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" type="number" min="0" /></div><div><Label>Meta mensal de peças</Label><Input value={unitsGoal} onChange={event => setUnitsGoal(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" type="number" min="0" /></div><div><Label>Margem mínima (%)</Label><Input value={minMargin} onChange={event => setMinMargin(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" /></div><div><Label>Margem desejada (%)</Label><Input value={desiredMargin} onChange={event => setDesiredMargin(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" /></div><div><Label>Imposto sobre venda (%)</Label><Input value={tax} onChange={event => setTax(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" /></div><div className="rounded-xl border border-cyan-300/10 bg-cyan-300/5 p-4"><p className="text-xs font-medium text-cyan-100">Histórico preservado</p><p className="mt-2 text-xs leading-5 text-slate-400">Alterar a cotação não muda compras e vendas anteriores. Somente operações futuras usam o novo parâmetro.</p></div></div><Button disabled={pending || !settings} onClick={submit} className="mt-6 bg-cyan-300 text-slate-950 hover:bg-cyan-200">{pending ? "Salvando..." : "Salvar configurações"}</Button></CardContent></Card></> }

function ProductDialog({ open, onOpenChange, onSubmit, pending }: { open: boolean; onOpenChange: (value: boolean) => void; onSubmit: (input: any) => void; pending: boolean }) { const [name, setName] = useState(""); const [team, setTeam] = useState(""); const [league, setLeague] = useState(""); const [collection, setCollection] = useState(""); const [category, setCategory] = useState("Torcedor"); const [size, setSize] = useState(""); const [price, setPrice] = useState(""); const [usd, setUsd] = useState(""); const [imageDataUrl, setImageDataUrl] = useState(""); return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[90vh] overflow-y-auto border-white/10 bg-slate-950 text-slate-100 sm:max-w-2xl"><DialogHeader><DialogTitle className="font-display text-xl">Novo produto</DialogTitle></DialogHeader><p className="text-xs leading-5 text-slate-500">O código é criado automaticamente no padrão COD001. Preencha custos e preço para que a precificação fique pronta desde o cadastro.</p><div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Label>Nome da peça</Label><Input value={name} onChange={event => setName(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" placeholder="Ex.: Camisa Flamengo Home" /></div><div><Label>Time</Label><Input value={team} onChange={event => setTeam(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" placeholder="Flamengo" /></div><div><Label>Liga/Campeonato</Label><Input value={league} onChange={event => setLeague(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" placeholder="Brasileirão" /></div><div><Label>Coleção/Temporada</Label><Input value={collection} onChange={event => setCollection(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" placeholder="2026/27" /></div><div><Label>Categoria</Label><Input value={category} onChange={event => setCategory(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" /></div><div><Label>Tamanho</Label><Input value={size} onChange={event => setSize(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" placeholder="GG" /></div><div><Label>Valor US$</Label><Input value={usd} onChange={event => setUsd(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" placeholder="10,00" /></div><div><Label>Preço de venda (R$)</Label><Input value={price} onChange={event => setPrice(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" inputMode="decimal" placeholder="180,00" /></div><div className="sm:col-span-2"><Label>Foto da peça</Label><Input type="file" accept="image/png,image/jpeg,image/webp" className="mt-2 border-white/10 bg-white/5 text-slate-300" onChange={event => { const file = event.target.files?.[0]; if (!file) return setImageDataUrl(""); if (file.size > 4 * 1024 * 1024) return toast.error("A foto deve ter no máximo 4 MB."); const reader = new FileReader(); reader.onload = () => setImageDataUrl(String(reader.result)); reader.readAsDataURL(file); }} /><p className="mt-1 text-[10px] text-slate-500">PNG, JPG ou WEBP com até 4 MB. A imagem é armazenada em storage seguro.</p></div></div><div className="mt-2 flex justify-end gap-2"><Button variant="outline" onClick={() => onOpenChange(false)} className="border-white/10 bg-white/5 text-slate-200">Cancelar</Button><Button disabled={!name || pending} onClick={() => onSubmit({ name, team, league, collection, category, size, listPriceCents: cents(price), usdValueCents: cents(usd), internationalShippingCents: 0, domesticShippingCents: 0, importFeesCents: 0, packagingCostCents: 0, otherCostsCents: 0, imageDataUrl: imageDataUrl || undefined })} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">{pending ? "Criando..." : "Criar produto"}</Button></div></DialogContent></Dialog> }

function ProductEditForm({ product, suppliers, onClose, onSave }: { product: Product; suppliers: any[]; onClose: () => void; onSave: (product: Product, changes: Record<string, unknown>) => void }) {
  const [name, setName] = useState(product.name); const [team, setTeam] = useState(product.team || ""); const [league, setLeague] = useState(product.league || ""); const [collection, setCollection] = useState(product.collection || ""); const [category, setCategory] = useState(product.category || ""); const [size, setSize] = useState(product.size || ""); const [shirtType, setShirtType] = useState(product.shirtType || "Casa"); const [color, setColor] = useState(product.predominantColor || ""); const [supplierId, setSupplierId] = useState(product.supplierId ? String(product.supplierId) : "none"); const [supplierUrl, setSupplierUrl] = useState(product.supplierUrl || ""); const [quote, setQuote] = useState(((product.quoteMicros || 0) / 1000000).toFixed(2)); const [price, setPrice] = useState(asInputValue(product.listPriceCents)); const [usd, setUsd] = useState(asInputValue(product.usdValueCents)); const [internationalShipping, setInternationalShipping] = useState(asInputValue(product.internationalShippingCents)); const [domesticShipping, setDomesticShipping] = useState(asInputValue(product.domesticShippingCents)); const [importFees, setImportFees] = useState(asInputValue(product.importFeesCents)); const [packaging, setPackaging] = useState(asInputValue(product.packagingCostCents)); const [otherCosts, setOtherCosts] = useState(asInputValue(product.otherCostsCents)); const [notes, setNotes] = useState(product.notes || ""); const [imageDataUrl, setImageDataUrl] = useState(""); const [imageError, setImageError] = useState("");
  const inputClass = "mt-2 border-white/10 bg-white/5 text-white";
  return <Dialog open onOpenChange={open => !open && onClose()}><DialogContent className="max-h-[90vh] overflow-y-auto border-white/10 bg-slate-950 text-slate-100 sm:max-w-2xl"><DialogHeader><DialogTitle>Editar produto completo</DialogTitle></DialogHeader><p className="text-xs leading-5 text-slate-500">A edição atualiza o cadastro e os parâmetros usados em simulações futuras. Compras e vendas anteriores preservam seus valores históricos.</p><div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Label>Nome da peça</Label><Input value={name} onChange={event => setName(event.target.value)} className={inputClass} /></div><div><Label>Time</Label><Input value={team} onChange={event => setTeam(event.target.value)} className={inputClass} /></div><div><Label>Liga/Campeonato</Label><Input value={league} onChange={event => setLeague(event.target.value)} className={inputClass} /></div><div><Label>Coleção/Temporada</Label><Input value={collection} onChange={event => setCollection(event.target.value)} className={inputClass} /></div><div><Label>Categoria</Label><Input value={category} onChange={event => setCategory(event.target.value)} className={inputClass} /></div><div><Label>Tamanho</Label><Input value={size} onChange={event => setSize(event.target.value)} className={inputClass} /></div><div><Label>Cor predominante</Label><Input value={color} onChange={event => setColor(event.target.value)} className={inputClass} /></div><div><Label>Tipo de camisa</Label><Select value={shirtType} onValueChange={setShirtType}><SelectTrigger className={inputClass}><SelectValue /></SelectTrigger><SelectContent>{["Casa", "Fora", "Especial", "Retrô"].map(type => <SelectItem key={type} value={type}>{type}</SelectItem>)}</SelectContent></Select></div><div><Label>Fornecedor</Label><Select value={supplierId} onValueChange={setSupplierId}><SelectTrigger className={inputClass}><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Sem fornecedor vinculado</SelectItem>{suppliers.map(supplier => <SelectItem key={supplier.id} value={String(supplier.id)}>{supplier.name}</SelectItem>)}</SelectContent></Select></div><div><Label>URL de origem/fornecedor</Label><Input value={supplierUrl} onChange={event => setSupplierUrl(event.target.value)} type="url" placeholder="https://" className={inputClass} /></div><div><Label>Cotação vinculada (R$)</Label><Input value={quote} onChange={event => setQuote(event.target.value)} inputMode="decimal" className={inputClass} /></div><div><Label>Preço de venda (R$)</Label><Input value={price} onChange={event => setPrice(event.target.value)} inputMode="decimal" className={inputClass} /></div><div><Label>Valor US$</Label><Input value={usd} onChange={event => setUsd(event.target.value)} inputMode="decimal" className={inputClass} /></div><div><Label>Frete internacional (R$)</Label><Input value={internationalShipping} onChange={event => setInternationalShipping(event.target.value)} inputMode="decimal" className={inputClass} /></div><div><Label>Frete nacional (R$)</Label><Input value={domesticShipping} onChange={event => setDomesticShipping(event.target.value)} inputMode="decimal" className={inputClass} /></div><div><Label>Impostos de importação (R$)</Label><Input value={importFees} onChange={event => setImportFees(event.target.value)} inputMode="decimal" className={inputClass} /></div><div><Label>Embalagem (R$)</Label><Input value={packaging} onChange={event => setPackaging(event.target.value)} inputMode="decimal" className={inputClass} /></div><div><Label>Outros custos (R$)</Label><Input value={otherCosts} onChange={event => setOtherCosts(event.target.value)} inputMode="decimal" className={inputClass} /></div><div className="sm:col-span-2"><Label>Observações</Label><Textarea value={notes} onChange={event => setNotes(event.target.value)} className={inputClass} placeholder="Detalhes de fornecedor, condição da peça ou observações internas" /></div><div className="sm:col-span-2"><Label>Trocar foto da camisa</Label><Input type="file" accept="image/png,image/jpeg,image/webp" className={inputClass} onChange={event => { const file = event.target.files?.[0]; setImageError(""); if (!file) return setImageDataUrl(""); if (file.size > 4 * 1024 * 1024) { setImageDataUrl(""); setImageError("A imagem deve ter no máximo 4 MB."); return; } const reader = new FileReader(); reader.onload = () => setImageDataUrl(String(reader.result)); reader.onerror = () => setImageError("Não foi possível ler esta imagem."); reader.readAsDataURL(file); }} /><p className={`mt-1 text-[10px] ${imageError ? "text-orange-200" : "text-slate-500"}`}>{imageError || (imageDataUrl ? "Nova foto pronta para salvar." : "PNG, JPG ou WEBP com até 4 MB.")}</p></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={onClose} className="border-white/10 bg-white/5 text-white">Cancelar</Button><Button onClick={() => { if (!name.trim()) return toast.error("Informe o nome do produto."); if (supplierUrl && !/^https?:\/\//i.test(supplierUrl)) return toast.error("Informe uma URL válida iniciando com http:// ou https://."); onSave(product, { name, team, league, collection, category, size, shirtType, predominantColor: color, supplierId: supplierId === "none" ? null : Number(supplierId), supplierUrl: supplierUrl || null, quoteMicros: Math.round(Number(quote.replace(",", ".")) * 1000000), listPriceCents: cents(price), usdValueCents: cents(usd), internationalShippingCents: cents(internationalShipping), domesticShippingCents: cents(domesticShipping), importFeesCents: cents(importFees), packagingCostCents: cents(packaging), otherCostsCents: cents(otherCosts), notes, imageDataUrl: imageDataUrl || undefined }); onClose(); }} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">Salvar alterações</Button></div></DialogContent></Dialog>;
}

function StockEntryForm({ product, onClose, onSave }: { product: Product; onClose: () => void; onSave: (product: Product, quantity: string, cost: string) => void }) { const [quantity, setQuantity] = useState("1"); const [cost, setCost] = useState("0,00"); return <Dialog open onOpenChange={open => !open && onClose()}><DialogContent className="border-white/10 bg-slate-950 text-slate-100"><DialogHeader><DialogTitle>Adicionar estoque</DialogTitle></DialogHeader><p className="text-sm text-slate-400">Entrada para <strong className="text-white">{product.name}</strong>. Essa movimentação ficará registrada no histórico.</p><div className="grid gap-4 sm:grid-cols-2"><div><Label>Quantidade</Label><Input aria-label="Quantidade de entrada" type="number" min="1" value={quantity} onChange={event => setQuantity(event.target.value)} className="mt-2 border-white/10 bg-white/5 text-white" /></div><div><Label>Custo unitário (R$)</Label><Input aria-label="Custo unitário da entrada em reais" value={cost} onChange={event => setCost(event.target.value)} inputMode="decimal" className="mt-2 border-white/10 bg-white/5 text-white" /></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={onClose} className="border-white/10 bg-white/5 text-white">Cancelar</Button><Button onClick={() => { if (Number(quantity) < 1) return toast.error("Informe uma quantidade válida."); onSave(product, quantity, cost); onClose(); }} className="bg-emerald-300 text-slate-950 hover:bg-emerald-200">Registrar entrada</Button></div></DialogContent></Dialog>; }
